SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.company_type ct, public.info_type it, public.movie_companies mc, public.movie_info mi WHERE title.id = mi.movie_id AND title.id = mc.movie_id AND ct.id = mc.company_type_id AND it.id = mi.info_type_id AND ct.kind = 'production companies' AND (mi.info = 'Sweden' OR mi.info = 'Norway' OR mi.info = 'Germany' OR mi.info = 'Denmark' OR mi.info = 'Swedish' OR mi.info = 'Denish' OR mi.info = 'Norwegian' OR mi.info = 'German' OR mi.info = 'USA' OR mi.info = 'American') AND title.production_year > 1990);
